import { useState, useEffect, useCallback, useMemo } from 'react'
import { getDeviceCabinetSpecList } from '@/apis/admin/site'
import { ResultEnum } from '@/utils/enums/httpEnum'
import type { SiteTypes } from '@/apis/admin/site'
import { GRID_SPEC_OPTIONS } from '@/constants'

/**
 * 获取设备柜子规格 Hook
 *
 * 使用 /admin/common-site/device-cabinet-spec/list 接口获取柜子规格数据
 * 返回原始规格数据，使用时按需转换
 */
export function useDeviceCabinetSpec() {
  const [specs, setSpecs] = useState<SiteTypes.DeviceCabinetSpecDto[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // 获取规格列表
  const fetchSpecs = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const res = await getDeviceCabinetSpecList()
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        setSpecs(res.data.list)
      } else {
        setError('获取规格列表失败')
      }
    } catch (e) {
      console.error('获取柜子规格失败:', e)
      setError('获取规格列表失败')
    } finally {
      setLoading(false)
    }
  }, [])

  // 组件挂载时获取数据
  useEffect(() => {
    fetchSpecs()
  }, [fetchSpecs])

  // 柜机规格选项列表（主柜和副柜共用）
  const specOptions = useMemo(() => {
    return specs.map(spec => ({
      label: `${spec.specName}：大${spec.bigGrid} / 中${spec.middleGrid} / 小${spec.smallGrid}（共${spec.totalGrid}格口）`,
      value: spec.id
    }))
  }, [specs])

  // 根据 id 获取柜子规格
  const getCabinetSpecById = useCallback(
    (id: number) => {
      return specs.find(spec => spec.id === id)
    },
    [specs]
  )

  // 格口规格选项（用于商品编辑等场景）
  const gridSpecOptions = useMemo(() => {
    if (specs.length === 0) {
      return []
    }
    return GRID_SPEC_OPTIONS
  }, [specs])

  return {
    // 原始规格数据
    specs,
    // 柜机规格选项列表（主柜和副柜共用）
    specOptions,
    // 查找方法
    getCabinetSpecById,
    // 格口规格选项
    gridSpecOptions,
    // 状态
    loading,
    error,
    refresh: fetchSpecs
  }
}

export default useDeviceCabinetSpec
